NAME_MAP = {
    'Coach': 'Coach', 'Le Doubs': 'Le Doubs', 'Ricardo': 'Ricardo',
    'La Dame blanche': 'La Dame blanche', 'Seb': 'Seb', 'Malherbe': 'Malherbe',
    'Dreux': 'Dreux', 'Mathieu': 'Mathieu', 'Ben': 'Ben',
}

def run():
    sys.path.insert(0, os.path.dirname(__file__))
    from database import get_db, q, qone, qall

    conn = get_db()
    print("Connexion DB OK")

    # Récupérer la saison active
    season = qone(conn, "SELECT * FROM seasons WHERE is_active=1")
    if not season:
        print("ERREUR: Aucune saison active")
        return
    print(f"Saison active: {season['name']} (id={season['id']})")

    # Récupérer tous les utilisateurs
    users = {u['username']: u['id'] for u in qall(conn, "SELECT id, username FROM users WHERE is_admin=0")}
    print(f"Joueurs trouvés: {list(users.keys())}")

    total_pronos = 0
    total_estimations = 0
    errors = []

    for jn_str, data in ODS_DATA.items():
        jn = int(jn_str)
        results = data['results']
        pronostics = data['pronostics']
        estimations = data['estimations']

        # Récupérer la journée
        matchday = qone(conn, "SELECT * FROM matchdays WHERE season_id=%s AND number=%s",
                       (season['id'], jn))
        if not matchday:
            errors.append(f"J{jn}: journée introuvable")
            continue

        # Récupérer les matchs de cette journée
        matches = qall(conn, "SELECT * FROM matches WHERE matchday_id=%s ORDER BY kickoff_time",
                      (matchday['id'],))
        if not matches:
            errors.append(f"J{jn}: aucun match trouvé")
            continue

        print(f"J{jn}: {len(matches)} matchs, {len(results)} résultats")

        # Insérer les pronostics
        for player, pronos in pronostics.items():
            user_id = users.get(player)
            if not user_id:
                errors.append(f"J{jn}: joueur '{player}' introuvable")
                continue

            for i, prono in enumerate(pronos):
                if prono is None or i >= len(matches):
                    continue
                match = matches[i]
                home_score, away_score = prono
                try:
                    q(conn, """
                        INSERT INTO pronostics (user_id, match_id, home_score, away_score)
                        VALUES (%s, %s, %s, %s)
                        ON CONFLICT(user_id, match_id) DO UPDATE SET
                            home_score=EXCLUDED.home_score, away_score=EXCLUDED.away_score
                    """, (user_id, match['id'], home_score, away_score))
                    total_pronos += 1
                except Exception as e:
                    errors.append(f"J{jn} {player} match{i}: {e}")

        # Insérer les estimations
        for player, estimation in estimations.items():
            if estimation is None:
                continue
            user_id = users.get(player)
            if not user_id:
                continue
            try:
                q(conn, """
                    INSERT INTO score_estimates (user_id, matchday_id, estimated_score)
                    VALUES (%s, %s, %s)
                    ON CONFLICT(user_id, matchday_id) DO UPDATE SET
                        estimated_score=EXCLUDED.estimated_score
                """, (user_id, matchday['id'], estimation))
                total_estimations += 1
            except Exception as e:
                errors.append(f"J{jn} {player} estimation: {e}")

    conn.commit()
    conn.close()

    print(f"\n=== RÉSULTAT ===")
    print(f"Pronostics insérés: {total_pronos}")
    print(f"Estimations insérées: {total_estimations}")
    if errors:
        print(f"Erreurs ({len(errors)}):")
        for e in errors[:20]:
            print(f"  - {e}")
    else:
        print("Aucune erreur !")

if __name__ == '__main__':
    run()
